    func test_irfft() {
        let spec = MfArray(real: SPEC_RE, imag: SPEC_IM)
        XCTAssertClose(Matft.fft.irfft(spec, norm: .backward), MfArray([1.3333333333333333, 0.5610042339640731, 2.093696304415178, -0.33333333333333326, 0.07297036225148826, 0.2723290993692602] as [Double], mftype: .Double, shape: [6]), rtol: 1e-09, atol: 1e-09, "Matft.fft.irfft(spec, norm: .backward)")
        XCTAssertClose(Matft.fft.irfft(spec, number: 5, norm: .backward), MfArray([1.0, 1.4935842582856074, 1.455451914986102, -0.6262723082360391, 0.6772361349643297] as [Double], mftype: .Double, shape: [5]), rtol: 1e-09, atol: 1e-09, "Matft.fft.irfft(spec, number: 5, norm: .backward)")
        XCTAssertClose(Matft.fft.irfft(spec, number: 7, norm: .backward), MfArray([1.5714285714285714, 0.007041093432447917, 1.9698777740651678, 0.5475731866259931, -0.4791597984549811, 0.37208388626117245, 0.011155286641628142] as [Double], mftype: .Double, shape: [7]), rtol: 1e-09, atol: 1e-09, "Matft.fft.irfft(spec, number: 7, norm: .backward)")
        XCTAssertClose(Matft.fft.irfft(spec, number: 3, norm: .backward), MfArray([2.0, 2.1547005383792515, -0.15470053837925146] as [Double], mftype: .Double, shape: [3]), rtol: 1e-09, atol: 1e-09, "Matft.fft.irfft(spec, number: 3, norm: .backward)")
        XCTAssertClose(Matft.fft.irfft(spec, number: 10, norm: .backward), MfArray([1.1, 0.24773582302621186, 0.2907711951324589, 1.490655942007901, 0.8655833283032618, -0.5, -0.08017313167829335, 0.3183610523670467, -0.17618139175742736, 0.4432471825988409] as [Double], mftype: .Double, shape: [10]), rtol: 1e-09, atol: 1e-09, "Matft.fft.irfft(spec, number: 10, norm: .backward)")
