    func test_windows() {
        XCTAssertEqual(Matft.hanning(0).shape, [0])
        XCTAssertClose(Matft.hanning(1), MfArray([1.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-12, atol: 1e-12, "Matft.hanning(1)")
        XCTAssertClose(Matft.hanning(2), MfArray([0.0, 0.0] as [Double], mftype: .Double, shape: [2]), rtol: 1e-12, atol: 1e-12, "Matft.hanning(2)")
        XCTAssertClose(Matft.hanning(5), MfArray([0.0, 0.5, 1.0, 0.5, 0.0] as [Double], mftype: .Double, shape: [5]), rtol: 1e-12, atol: 1e-12, "Matft.hanning(5)")
        XCTAssertEqual(Matft.hamming(0).shape, [0])
        XCTAssertClose(Matft.hamming(1), MfArray([1.0] as [Double], mftype: .Double, shape: [1]), rtol: 1e-12, atol: 1e-12, "Matft.hamming(1)")
        XCTAssertClose(Matft.hamming(2), MfArray([0.08000000000000002, 0.08000000000000002] as [Double], mftype: .Double, shape: [2]), rtol: 1e-12, atol: 1e-12, "Matft.hamming(2)")
