        XCTAssertClose(Matft.audio.pad_or_trim(P.T.T, length: 1, axis: 0), MfArray([-5.0, -4.0, -3.0, -2.0] as [Double], mftype: .Double, shape: [1, 4]), rtol: 0, atol: 0, "Matft.audio.pad_or_trim(P.T.T, length: 1, axis: 0)")
    }

